def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    import datetime
    # Validate input
    if not isinstance(nanoseconds, (int, float)):
        raise TypeError(f"nanoseconds must be int or float, got {type(nanoseconds).__name__}")
    # Convert nanoseconds to seconds
    seconds = nanoseconds / 1_000_000_000
    # Use UTC as base
    try:
        dt = datetime.datetime.utcfromtimestamp(seconds)
    except (OverflowError, OSError, ValueError) as e:
        raise ValueError(f"nanoseconds value {nanoseconds} is out of range for timestamp conversion") from e
    # Extract time components
    hour = dt.hour
    minute = dt.minute
    second = dt.second
    microsecond = dt.microsecond
    # Handle timezone
    if tz is None:
        return datetime.time(hour, minute, second, microsecond)
    # tz can be a datetime.tzinfo instance
    if isinstance(tz, datetime.tzinfo):
        return datetime.time(hour, minute, second, microsecond, tzinfo=tz)
    # tz can be an offset in seconds (int or float)
    if isinstance(tz, (int, float)):
        offset = datetime.timedelta(seconds=tz)
        tzinfo = datetime.timezone(offset)
        return datetime.time(hour, minute, second, microsecond, tzinfo=tzinfo)
    # If tz is a string, try to parse common formats
    if isinstance(tz, str):
        try:
            # Attempt to parse as ISO offset e.g. "+02:00" or "-0500"
            if tz.startswith(('+', '-')):
                # Ensure format HH:MM or HHMM
                if ':' not in tz:
                    tz = tz[:3] + ':' + tz[3:]
                offset = datetime.datetime.strptime(tz, "%z").utcoffset()
                tzinfo = datetime.timezone(offset)
                return datetime.time(hour, minute, second, microsecond, tzinfo=tzinfo)
        except Exception:
            pass
    raise TypeError(f"Unsupported tz type: {type(tz).__name__}")

