def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None

    # Try to use the standard ISO format if available
    try:
        # Most time-like objects (datetime.time, datetime.datetime, etc.) provide isoformat()
        return value.isoformat()
    except AttributeError:
        # If the object does not have isoformat, fall back to a common string format
        try:
            return value.strftime("%H:%M:%S.%f")
        except Exception:
            # If all attempts fail, raise a clear error
            raise TypeError(
                f"Expected a time-like object with isoformat() or strftime() method, got {type(value).__name__}"
            )
    except Exception as exc:
        # Catch any other unexpected errors and re-raise as TypeError for consistency
        raise TypeError(f"Error dehydrating time value: {exc}") from exc

