def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point instance
    :type value: Point
    :return: dict representation of the point or None if value is None
    """
    if value is None:
        return None
    try:
        # Extract coordinates; raise if required attributes are missing
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError as exc:
        raise TypeError(
            "Expected a Point-like object with 'x' and 'y' attributes"
        ) from exc

    # Optional third coordinate
    z = getattr(value, "z", None)

    result = {"x": x, "y": y}
    if z is not None:
        result["z"] = z
    return result

