def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        for idx, item in enumerate(self):
            if item == key:
                return idx
        # If we get here, key was not found
        raise ValueError(f"{key!r} is not in the collection")
    except TypeError:
        # self is not iterable
        raise TypeError("The object is not iterable and cannot be indexed")
    except Exception as e:
        # Catch any other unexpected errors
        raise RuntimeError(f"Unexpected error while retrieving index: {e}") from e

