def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to get all values from the record
    try:
        all_values = list(self.values())
    except AttributeError:
        raise TypeError("The object does not support a values() method")

    # If no keys are specified, return all values
    if not keys:
        return all_values

    # Collect the requested values
    result = []
    for key in keys:
        if isinstance(key, int):
            # Handle negative indices as well
            if -len(all_values) <= key < len(all_values):
                result.append(all_values[key])
        elif isinstance(key, str):
            if key in self:
                result.append(self[key])
        else:
            raise TypeError(f"Key must be an int or str, got {type(key).__name__}")

    return result

