def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation of arguments
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Ensure field names are strings
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field name {f!r} is not a string")

    # Define the constructor for the new class
    def __init__(self, *coords, srid=None, **kwargs):
        if len(coords) != len(fields):
            raise ValueError(f"Expected {len(fields)} coordinates, got {len(coords)}")
        # Assign coordinate values to the corresponding fields
        for field_name, value in zip(fields, coords):
            setattr(self, field_name, value)
        # Handle SRID
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} not found in srid_map")
            self.srid = srid
        else:
            self.srid = None
        # Store any additional keyword arguments as attributes
        for key, value in kwargs.items():
            setattr(self, key, value)

    # Representation method for debugging
    def __repr__(self):
        field_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in fields)
        return f"<{name} {field_str}, srid={self.srid}>"

    # Build the class dictionary
    class_dict = {
        "__init__": __init__,
        "__repr__": __repr__,
        "__doc__": f"{name} point with fields {fields}",
        "SRID_MAP": srid_map,
    }

    # Create and return the new class type
    return type(name, (object,), class_dict)

