def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if seq is None:
        raise TypeError("seq must not be None")
    try:
        items = list(seq)
    except Exception as exc:
        raise TypeError("seq must be a sequence") from exc

    # Use a simple linear congruential generator seeded by the hash of the sequence
    seed = hash(tuple(items)) & 0xFFFFFFFF
    n = len(items)
    for i in range(n - 1, 0, -1):
        seed = (seed * 1103515245 + 12345) & 0xFFFFFFFF
        j = seed % (i + 1)
        items[i], items[j] = items[j], items[i]
    return items

