def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    s = s.strip()
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for part in parts:
        if part.isdigit():
            nums.append(int(part))
        else:
            # try to extract leading digits
            num = ''
            for ch in part:
