def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    # Validate parameters
    if maxsize is not None:
        if not isinstance(maxsize, int):
            raise TypeError("maxsize must be an integer or None")
        if maxsize < 0:
            raise ValueError("maxsize must be >= 0 or None")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a bool")

    def decorating_function(user_function):
        if not callable(user_function):
            raise TypeError("lru_cache can only be applied to callable objects")

        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            # Build key
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent order
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types in key
                new_key = []
                for item in key:
                    if isinstance(item, tuple) and len(item) == 2:
                        # keyword argument
                        k, v = item
                        new_key.append((k, v, type(v)))
                    else:
                        new_key.append((item, type(item)))
                key = tuple(new_key)
            try:
                hash(key)
            except TypeError:
                raise TypeError("unhashable key")

            if key in cache:
                # Move key to end to mark as recently used
                order.remove(key)
                order.append(key)
                return cache[key]

            result = user_function(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Evict least recently used if cache is too big
            if maxsize is not None and maxsize > 0 and len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]

