def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Validate input
    if not isinstance(orderings, list):
        raise TypeError("orderings must be a list of lists")
    for o in orderings:
        if not isinstance(o, list):
            raise TypeError("each ordering must be a list")

    # Build graph: adjacency list and indegree count
    from collections import defaultdict, deque

    adj = defaultdict(set)   # node -> set of successors
    indegree = defaultdict(int)  # node -> indegree count
    nodes = set()

    for ordering in orderings:
        # Remove duplicates within the same ordering to avoid self loops
        seen_in_order = set()
        for i, a in enumerate(ordering):
            if a in seen_in_order:
                continue
            seen_in_order.add(a)
            nodes.add(a)
            for b in ordering[i+1:]:
                if b in seen_in_order:
                    continue
                if b not in adj[a]:
                    adj[a].add(b)
                    indegree[b] += 1
                    nodes.add(b)

    # Ensure all nodes have an indegree entry
    for n in nodes:
        indegree.setdefault(n, 0)

    # Determine first appearance order for tie-breaking
    first_appearance = {}
    for order_idx, ordering in enumerate(orderings):
        for pos, elem in enumerate(ordering):
            if elem not in first_appearance:
                first_appearance[elem] = (order_idx, pos)

    # Kahn's algorithm with priority queue based on first appearance
    import heapq
    heap = []
    for n in nodes:
        if indegree[n] == 0:
            heapq.heappush(heap, (first_appearance.get(n, (float('inf'), float('inf'))), n))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for succ in adj[node]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                heapq.heappush(heap, (first_appearance.get(succ, (float('inf'), float('inf'))), succ))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in orderings; cannot merge")

    return result

