    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Handle None or non-object inputs gracefully
    if object is None:
        return None

    # If the object (or class) has a __provides__ attribute, return it
    try:
        if hasattr(object, "__provides__"):
            return object.__provides__
    except Exception:
        # In case __provides__ access raises an unexpected error, fall back
        pass

    # If the object is a class, check its __provides__ attribute
    if isinstance(object, type):
        try:
            if hasattr(object, "__provides__"):
                return object.__provides__
        except Exception:
            pass

    # Fallback: try to return an empty Declaration from zope.interface
    try:
        from zope.interface.declarations import Declaration
        return Declaration()
    except Exception:
        # If zope.interface is not available or any other error occurs,
        # return None to indicate no interfaces are directly provided.
        return None

