def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Ensure the input is iterable and convert to a list
    try:
        class_list = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of types")

    # Validate that every element is a type
    for c in class_list:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a type")

    minimal = []
    seen = set()

    for c in class_list:
        if c in seen:
            continue

        # Check if c is a subclass of any other class in the list
        redundant = False
        for other in class_list:
            if other is c:
                continue
            if issubclass(c, other):
                redundant = True
                break

        if not redundant:
            minimal.append(c)
            seen.add(c)

    return minimal

