    try:
        iter(sequence)
    except TypeError:
        output.append(sequence)
        return output

    for item in sequence:
        # Skip expanding strings or bytes
        if isinstance(item, (str, bytes)):
            output.append(item)
            continue

        # Expand tuples, lists, or sets into individual elements
        if isinstance(item, (tuple, list, set)):
            output.extend(item)
            continue

        # If the item has an 'implements' attribute, keep it as a single spec
        if hasattr(item, "implements"):
            output.append(item)
            continue

        # If the item has an 'interfaces' attribute, expand it
        if hasattr(item, "interfaces"):
            interfaces = getattr(item, "interfaces")
            if isinstance(interfaces, (tuple, list, set)):
                output.extend(interfaces)
            else:
                output.append(interfaces)
            continue

        # Default: keep the item as is
        output.append(item)

    return output

