    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # Preserve existing bin keys but reset their values
        # If self.bins is not defined yet, start with an empty dict
        existing_bins = getattr(self, "bins", {})
        self.bins = {k: self.initial_value for k in existing_bins}
    else:
        # Use the make_bins method if available
        if hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            # Fallback: empty bins dictionary
            self.bins = {}

