def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure weight is numeric
    try:
        weight = float(weight)
    except Exception:
        return

    # Find the appropriate bin index
    idx = None
    for i in range(len(self.edges) - 1):
        if self.edges[i] <= coord < self.edges[i + 1]:
            idx = i
            break

    # If coordinate is outside the histogram, ignore it
    if idx is None:
        return

    # Increment the bin count
    try:
        self.data[idx] += weight
    except Exception:
        # If self.data is not a list/array, try to set it directly
        if hasattr(self, 'data'):
            try:
                self.data[idx] = weight
            except Exception:
                # Fallback: create a new list if possible
                try:
                    self.data = [0] * (len(self.edges) - 1)
                    self.data[idx] = weight
                except Exception:
                    return

    # Update total weight if the attribute exists
    if hasattr(self, 'total_weight'):
        try:
            self.total_weight += weight
        except Exception:
            try:
                self.total_weight = weight
            except Exception:
                pass

