def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input object
    if not hasattr(app, "spec"):
        raise ValueError("The provided app object does not have a 'spec' attribute.")
    spec = app.spec
    if not hasattr(spec, "manifest"):
        raise ValueError("The app spec does not contain a 'manifest' attribute.")
    manifest = spec.manifest
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("app.spec.manifest must be a list or tuple of resources.")

    # Default observer schema to apply when none is defined
    default_schema = {
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "status": {"type": "object"},
        },
    }

    # Iterate over each resource in the manifest
    for idx, resource in enumerate(manifest):
        try:
            # Skip if the resource is None or not a dict/object
            if resource is None:
                continue

            # Determine if the resource already has an observer schema
            has_schema = False
            if isinstance(resource, dict):
                has_schema = "observer_schema" in resource and resource["observer_schema"] is not None
            else:
                has_schema = hasattr(resource, "observer_schema") and getattr(resource, "observer_schema") is not None

            # If a schema is already defined, skip this resource
            if has_schema:
                continue

            # Apply the default schema
            if isinstance(resource, dict):
                resource["observer_schema"] = default_schema
            else:
                setattr(resource, "observer_schema", default_schema)

        except Exception as exc:
            # Log the error and continue with the next resource
            # (Assuming a logger is available; otherwise, re-raise)
            try:
                import logging
                logging.getLogger(__name__).warning(
                    f"Failed to set default observer schema for resource at index {idx}: {exc}"
                )
            except Exception:
                # If logging is not available, silently ignore
                pass
            continue

