def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple of digests")

    digests_used_set = set(digests_used)

    # Check that every digest listed in the manifest is actually used
    for fname, digest in manifest_files.items():
        if digest not in digests_used_set:
            raise ValueError(
                f"Digest for file '{fname}' ({digest}) is present in the manifest but not used"
            )

    # Check that every used digest is present in the manifest
    manifest_digests = set(manifest_files.values())
    for digest in digests_used_set:
        if digest not in manifest_digests:
            raise ValueError(
                f"Digest '{digest}' is used but not present in the manifest"
            )

    return True

