def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an int or str")

    # Helper to iterate over entries in inventory
    def iter_entries(inv):
        if isinstance(inv, dict):
            # If dict values are lists or iterables of entries
            for val in inv.values():
                if isinstance(val, (list, tuple, set)):
                    for e in val:
                        yield e
                else:
                    # single entry
                    yield val
        elif isinstance(inv, (list, tuple, set)):
            for e in inv:
                yield e
        else:
            raise TypeError("inventory must be a dict or iterable of entries")

    # Build a mapping from logical_path to all content_files across all versions
    all_path_to_files = {}
    # Also keep track of which logical paths appear in the target version
    target_paths = set()

    for entry in iter_entries(inventory):
        try:
            logical_path = entry.get('logical_path')
            content_file = entry.get('content_file')
            entry_version = entry.get('version')
        except AttributeError:
            # entry is not a dict-like object
            continue

        if logical_path is None or content_file is None:
            continue

        # Add to global mapping
        all_path_to_files.setdefault(logical_path, set()).add(content_file)

        # Record if this entry belongs to the target version
        if entry_version == version:
            target_paths.add(logical_path)

    if not target_paths:
        # No entries found for the requested version
        raise ValueError(f"No entries found for version {version}")

    # Build the final mapping for the target version
    result = {}
    for path in target_paths:
        result[path] = all_path_to_files.get(path, set())

    return result

