def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    import os
    import zipfile
    if not isinstance(zip_path, (str, bytes, os.PathLike)):
        raise TypeError("zip_path must be a path-like object or string")
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            names = [name for name in zf.namelist()
                     if not name.endswith('/') and not name.startswith('__MACOSX/') and not name.endswith('.DS_Store')]
            return names
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error reading zip file {zip_path}: {e}") from e

