def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not node or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                # Se o match for um elemento, devolve o próprio elemento;
                # se for um valor de texto, devolve o valor.
                match = matches[0]
                if hasattr(match, 'text'):
                    return match.text.strip() if isinstance(match.text, str) else match.text
                return match
        except Exception:
            # Ignora erros de XPath e continua com o próximo
            continue
    return None

