def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    try:
        indent_str = "  " * indent
        lines = [f"{indent_str}{self.__class__.__name__}("]

        # Gather attributes (excluding private ones)
        attrs = []
        for key, value in getattr(self, "__dict__", {}).items():
            if key.startswith("_"):
                continue
            if debug and key == "id":
                attrs.append(f"id={repr(value)}")
            elif isinstance(value, (list, tuple)):
                attrs.append(f"{key}=[{len(value)} items]")
            else:
                attrs.append(f"{key}={repr(value)}")

        if attrs:
            lines.append(f"{indent_str}  " + ", ".join(attrs))

        lines.append(f"{indent_str})")

        # Recursively pretty‑print children if iterable
        if hasattr(self, "__iter__"):
            for child in self:
                if hasattr(child, "pretty") and callable(child.pretty):
                    lines.append(child.pretty(indent + 1, debug))
                else:
                    child_str = repr(child)
                    lines.append("  " * (indent + 1) + child_str)

        return "\n".join(lines)

    except Exception as exc:
        # Return a readable error message instead of propagating
        return f"<Error in pretty: {exc}>"

