def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate that the hook is hashable (so it can be used as a dict key)
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError(f"Hook {hook!r} is not hashable: {exc}") from exc

    # Ensure the registry dictionary exists on the instance
    if not hasattr(self, "_registry"):
        self._registry = {}

    # Create a list for this hook if it doesn't already exist
    if hook not in self._registry:
        self._registry[hook] = []

    def decorator(func):
        """Register a handler function for the specified hook."""
        if not callable(func):
            raise TypeError("Handler must be a callable")
        # Avoid duplicate registration
        if func in self._registry[hook]:
            return func
        self._registry[hook].append(func)
        return func

    return decorator

