def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")

    # Build the full command
    full_cmd = cmd + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command '{' '.join(full_cmd)}' failed with return code {e.returncode}")
        raise
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{' '.join(full_cmd)}': {e}") from e

