def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    obj.validate()
            except Exception as e:
                valid = False
                if show_warnings:
                    try:
                        obj_id = getattr(obj, 'id', None)
                        print(f"Validation error in object {obj_id}: {e}")
                    except Exception:
                        print(f"Validation error in object {repr(obj)}: {e}")

        if check_digests:
            try:
                if hasattr(obj, 'check_digest'):
                    obj.check_digest()
            except Exception as e:
                valid = False
                if show_warnings:
                    try:
                        obj_id = getattr(obj, 'id', None)
                        print(f"Digest check failed for object {obj_id}: {e}")
                    except Exception:
                        print(f"Digest check failed for object {repr(obj)}: {e}")

        if valid:
            good_objects += 1

        # Recurse into children if iterable (but skip strings, bytes, and dicts)
        if hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes, dict)):
            for child in obj:
                _traverse(child)

    _traverse(self)
    return num_objects, good_objects

