def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return
    # Build a list of id strings
    id_list = []
    if isinstance(bug_ids, str):
        # split comma separated string
        id_list = [bid.strip() for bid in bug_ids.split(',') if bid.strip()]
    elif isinstance(bug_ids, (list, tuple, set)):
        for bid in bug_ids:
            # allow objects with an 'id' attribute
            if hasattr(bid, 'id'):
                bid = bid.id
            id_list.append(str(bid))
    else:
        # single value (int, str, object with id)
        if hasattr(bug_ids, 'id'):
            bug_ids = bug_ids.id
        id_list.append(str(bug_ids))
    # Merge with existing ids if present
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = [eid.strip() for eid in existing.split(',') if eid.strip()]
        else:
            existing_ids = [str(existing)]
        # Combine and deduplicate while preserving order
        combined = []
        seen = set()
        for eid in existing_ids + id_list:
            if eid not in seen:
                seen.add(eid)
                combined.append(eid)
        params['ids'] = ','.join(combined)
    else:
        params['ids'] = ','.join(id_list)

