def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate keys.
    MappingNode values are merged recursively; non-mapping values are overwritten
    by the last occurrence.
    """
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list of tuples")

    merged = {}
    key_nodes = {}

    for key_node, val_node in nodes:
        # Ensure key_node has a value attribute
        if not hasattr(key_node, "value"):
            raise ValueError("Key node must have a 'value' attribute")
        key = key_node.value

        if key in merged:
            existing_val = merged[key]
            # Merge only if both values are MappingNodes
            if isinstance(existing_val, type(val_node)) and isinstance(val_node, type(existing_val)):
                # Merge mapping node values recursively
                existing_list = existing_val.value if isinstance(existing_val.value, list) else []
                new_list = val_node.value if isinstance(val_node.value, list) else []
                merged_val = type(existing_val)(
