def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError(f"size must be a string, got {type(size).__name__}")

    s = size.strip()
    if not s:
        raise ValueError("size string is empty")

    # Separate numeric part and unit part
    num_part = []
    unit_part = []
    for i, ch in enumerate(s):
        if ch.isdigit() or ch == '.' or (ch == '-' and i == 0):
            num_part.append(ch)
        else:
            unit_part = s[i:].strip()
            break

    if not num_part:
        raise ValueError(f"no numeric value found in '{size}'")

    try:
        number = float(''.join(num_part))
    except ValueError as exc:
        raise ValueError(f"invalid numeric value in '{size}'") from exc

    unit = unit_part.lower()
    factor = 1
    if unit:
        # Handle common units
        if unit.startswith('k'):
            factor = 1000
        elif unit.startswith('m'):
            factor = 1000 ** 2
        elif unit.startswith('g'):
            factor = 1000 ** 3
        elif unit.startswith('t'):
            factor = 1000 ** 4
        elif unit.startswith('p'):
            factor = 1000 ** 5
        elif unit.startswith('e'):
            factor = 1000 ** 6
        else:
            raise ValueError(f"unknown unit '{unit_part}' in '{size}'")

    bytes_value = int(round(number * factor))
    return bytes_value

