def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Basic type checks
    if url is None:
        return None
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    import re
    from urllib.parse import quote

    # Pattern matches anything inside curly braces, e.g. {id}, {user-name}
    pattern = re.compile(r'\{([^{}]+)\}')

    def _repl(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing URL argument: {key}")
        value = url_args[key]
        if value is None:
            raise ValueError(f"URL argument '{key}' is None")
        # Convert to string and URL‑encode
        return quote(str(value), safe='')

    # Perform substitution
    return pattern.sub(_repl, url)

