def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET and sockaddr[0] == '127.0.0.1':
                return True
            if family == socket.AF_INET6 and sockaddr[0] == '::1':
                return True
        if host.lower() == 'localhost':
            return True
    except socket.gaierror:
        return False
    except Exception:
        return False
    return False

