def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if isinstance(commands, list) and not all(isinstance(c, str) for c in commands):
        raise TypeError("commands list must contain only strings")
    if not isinstance(args, (list, str)):
        raise TypeError("args must be a string or a list of strings")
    if isinstance(args, list) and not all(isinstance(a, str) for a in args):
        raise TypeError("args list must contain only strings")

    # Normalise commands to a list
    if isinstance(commands, str):
        commands = [commands]

    # Normalise args to a list of argument lists
    if isinstance(args, list) and all(isinstance(a, list) for a in args):
        # args is a list of lists, one per command
        if len(args) != len(commands):
            raise ValueError("Number of argument lists must match number of commands")
        arg_lists = args
    else:
        # args is a single list of strings (or a single string)
        if isinstance(args, str):
            args = [args]
        arg_lists = [args] * len(commands)

    outputs = []
    for cmd, arg_list in zip(commands, arg_lists):
        cmd_list = [cmd] + arg_list
        if verbose:
            print(f"Running command: {' '.join(cmd_list)}")
        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stderr=subprocess.DEVNULL if hide_stderr else None
            )
            if result.returncode != 0:
                raise subprocess.CalledProcessError(
                    result.returncode,
                    cmd_list,
                    output=result.stdout,
                    stderr=result.stderr
                )
            outputs.append(result.stdout)
            if verbose:
                print(result.stdout)
        except Exception as e:
            raise RuntimeError(f"Failed to run command {cmd_list}: {e}") from e

    return outputs[0] if len(outputs) == 1 else outputs

