def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """Find the roots in a transitive hierarchy defined by triples (child, prop, parent)."""
    # Validate inputs
    try:
        from rdflib import Graph, URIRef
    except Exception as exc:
        raise ImportError("rdflib is required for find_roots") from exc

    if not isinstance(graph, Graph):
        raise TypeError("graph must be an rdflib.Graph instance")
    if not isinstance(prop, URIRef):
        raise TypeError("prop must be an rdflib.URIRef instance")

    if roots is None:
        roots = set()
    else:
        if not isinstance(roots, set):
            raise TypeError("roots must be a set")

    # Collect all children and parents
    children = set()
    parents = set()
    try:
        for child, p, parent in graph.triples((None, prop, None)):
            children.add(child)
            parents.add(parent)
    except Exception as exc:
        raise RuntimeError(f"Error iterating over graph triples: {exc}") from exc

    # Roots are parents that are not children
    roots.update(parents - children)
    return roots

