def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import configparser
    import os
    import re
    import logging

    logger = logging.getLogger('config_loader')
    results = {}
    errors = []

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    elif not hasattr(config_filenames, '__iter__'):
        msg = f"config_filenames must be a string or iterable, got {type(config_filenames).__name__}"
        errors.append(logging.LogRecord('config_loader', logging.ERROR, '', 0, msg, None, None))
        return results, errors

    # Helper to resolve environment variables in a nested structure
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env(value):
        if isinstance(value, str):
            return env_pattern.sub(lambda m: os.getenv(m.group(1), ''), value)
        return value

    def _traverse_and_resolve(obj):
        if isinstance(obj, dict):
            return {k: _traverse_and_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_traverse_and_resolve(v) for v in obj]
        else:
            return _resolve_env(obj)

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except FileNotFoundError:
            msg = f"Configuration file not found: {fname}"
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
            continue
        except PermissionError:
            msg = f"Permission denied when reading configuration file: {fname}"
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
            continue
        except Exception as exc:
            msg = f"Error reading configuration file {fname}: {exc}"
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
            continue

        config = None
        # Try JSON
        try:
            config = json.loads(content)
        except json.JSONDecodeError:
            pass
        except Exception as exc:
            msg = f"JSON parsing error in {fname}: {exc}"
            errors.append(logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None))
            continue

        # If JSON failed, try ConfigParser (INI)
        if config is None:
            try:
                cp = configparser.ConfigParser()
                cp.read_file(f)
                config = {section: dict(cp.items(section)) for section in cp.sections()}
