def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation
    if not hasattr(hist, "bins"):
        raise ValueError("histogram object must have a 'bins' attribute")
    if not isinstance(field_names, (list, tuple)):
        raise ValueError("field_names must be a list or tuple")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    points = []
    bins = hist.bins
    # Try to get bin edges if available
    bin_edges = getattr(hist, "bin_edges", None)
    for i, bin_ in enumerate(bins):
        # Extract bin content
        if isinstance(bin_, tuple):
            content = bin_[0]
        elif hasattr(bin_, "content"):
            content = bin_.content
        elif hasattr(bin_, "value"):
            content = bin_.value
        else:
            content = bin_
        # Ensure numeric if no make_value
        if make_value is None and not isinstance(content, (int, float)):
            raise ValueError("Histogram contains non-numeric bin without make_value")
        # Apply make_value
        if make_value is None:
            values = (content,)
        else:
            try:
                values = make_value(content)
            except Exception as exc:
                raise ValueError(f"make_value raised an exception: {exc}") from exc
            if not isinstance(values, tuple):
                values = (values,)
        # Check field names length
        if len(values) != len(field_names):
            raise ValueError(f"make_value returned {len(values)} values, "
                             f"but field_names has {len(field_names)} entries")
        # Determine coordinate
        if get_coordinate == "left":
            if hasattr(bin_, "left"):
                coord = bin_.left
            elif bin_edges is not None:
                coord = bin_edges[i]
            else:
                raise ValueError("Cannot determine left coordinate for bin")
        elif get_coordinate == "right":
            if hasattr(bin_, "right"):
                coord = bin_.right
            elif bin_edges is not None:
                coord = bin_edges[i + 1]
            else:
                raise ValueError("Cannot determine right coordinate for bin")
        else:  # middle
            if hasattr(bin_, "center"):
                coord = bin_.center
            elif bin_edges is not None:
                coord = (bin_edges[i] + bin_edges[i + 1]) / 2.0
            else:
                raise ValueError("Cannot determine middle coordinate for bin")
        # Build point tuple
        point = (coord,) + values
        points.append(point)

    # Build graph representation
    graph = {"points": points}
    # Set scale
    if scale is True:
        graph["scale"] = getattr(hist, "scale", None)
    elif scale is not None:
        graph["scale"] = scale
    else:
        graph["scale"] = None

    return graph

