def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise TypeError("determineMetaclass requires at least one base class")
    # Validate that all bases are classes
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")
    # Validate explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a class")
        candidate = explicit_mc
    else:
        candidate = type(bases[0])
    # Resolve the most derived common metaclass
    for b in bases:
        m = type(b)
        if candidate is m:
            continue
        if issubclass(candidate, m):
            # candidate is more derived, keep it
            continue
        if issubclass(m, candidate):
            candidate = m
            continue
        # No common ancestor metaclass
        raise TypeError(
            f"Metaclass conflict: {candidate.__name__} and {m.__name__} are incompatible"
        )
    return candidate

