def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Check for a public message
        if hasattr(request, "public_message"):
            public_msg = getattr(request, "public_message")
            if public_msg:
                return True

        # Check for a private message
        if hasattr(request, "private_message"):
            private_msg = getattr(request, "private_message")
            if private_msg:
                return True

        # Check for a legacy payload
        if hasattr(request, "legacy_payload"):
            legacy = getattr(request, "legacy_payload")
            if legacy:
                return True

        return False
    except Exception:
        # In case of any unexpected error, treat as not a Diaspora request
        return False

