def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if dt is None:
        raise ValueError("dt cannot be None")
    if isinstance(dt, datetime.datetime):
        # If timezone-aware, convert to UTC and use 'Z' suffix
        if dt.tzinfo is not None:
            try:
                dt_utc = dt.astimezone(datetime.timezone.utc)
            except Exception:
                # Fallback: assume UTC if conversion fails
                dt_utc = dt
            return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
        else:
            return dt.strftime("%Y-%m-%dT%H:%M:%S")
    elif isinstance(dt, datetime.date):
        return dt.strftime("%Y-%m-%d")
    else:
        raise TypeError("dt must be a datetime.datetime or datetime.date instance")

