def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        url_pattern = re.compile(r'(https?://[^\s<]+|www\.[^\s<]+)', re.IGNORECASE)
        email_pattern = re.compile(r'[\w\.-]+@[\w\.-]+\.\w+', re.IGNORECASE)

        def replace_url(match):
            url = match.group(0)
            href = url
            if not re.match(r'^https?://', href, re.IGNORECASE):
                href = 'http://' + href
            return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

        def replace_email(match):
            email = match.group(0)
            return f'<a href="mailto:{email}">{email}</a>'

        # Linkify URLs
        text = url_pattern.sub(replace_url, text)
        # Linkify emails
        text = email_pattern.sub(replace_email, text)
        return text
    except Exception as e:
        raise RuntimeError(f"Error processing text links: {e}") from e

