def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed author did actually generate this message."""
    try:
        if public_key is None:
            raise ValueError("public_key is required")
        if doc is None:
            raise ValueError("doc is required")
        if signature is None:
            raise ValueError("signature is required")

        # Canonicalise the XML document
        if hasattr(doc, "getroottree"):
            xml_bytes = etree.tostring(doc, method="c14n", exclusive=True, with_comments=False)
        else:
            try:
                root = etree.fromstring(doc)
                xml_bytes = etree.tostring(root, method="c14n", exclusive=True, with_comments=False)
            except Exception as e:
                raise ValueError("doc must be an lxml element or XML string") from e

        # Decode the signature if it is a base64 string
        if isinstance(signature, str):
            try:
                signature_bytes = base64.b64decode(signature)
            except Exception as e:
                raise ValueError("signature must be bytes or base64-encoded string") from e
        elif isinstance(signature, bytes):
            signature_bytes = signature
        else:
            raise ValueError("signature must be bytes or base64-encoded string")

        # Verify the signature using the provided public key
        public_key.verify(
            signature_bytes,
            xml_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

