def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")
    doc = document.strip()
    # Try JSON parsing
    try:
        json_module = __import__('json')
        data = json_module.loads(doc)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    # Try XRD (XML) parsing
    try:
        ET = __import__('xml.etree.ElementTree', fromlist=['ElementTree'])
        root = ET.fromstring(doc)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        result: Dict = {}
        subject = root.find('xrd:Subject', ns)
        if subject is not None and subject.text:
            result['subject'] = subject.text
        aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]
        if aliases:
            result['aliases'] = aliases
        links = []
        for link in root.findall('xrd:Link', ns):
            rel = link.attrib.get('rel')
            href = link.attrib.get('href')
            if rel and href:
                links.append({'rel': rel, 'href': href})
        if links:
            result['links'] = links
        if result:
            return result
    except Exception:
        pass
    raise ValueError("Unable to parse Diaspora webfinger document")

