    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str):
        raise TypeError("handle must be a string")
    if '@' not in handle:
        raise ValueError("handle must be in the form user@domain")

    # Construct the webfinger URL
    try:
        user, domain = handle.split('@', 1)
    except ValueError:
        raise ValueError("handle must contain exactly one '@' character")

    resource = f"acct:{handle}"
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    # Retrieve and parse the JSON response
    try:
        import urllib.request
        import urllib.error
        import json

        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return {}
            raw = response.read().decode('utf-8')
            return json.loads(raw)
    except (urllib.error.URLError, urllib.error.HTTPError, json.JSONDecodeError):
        # Return an empty dict on any error (network, HTTP, or JSON parsing)
        return {}

