def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if parser_dict is None:
        raise ValueError("parser_dict cannot be None")
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")

    # Work on a shallow copy to avoid mutating the caller's data
    resolved = parser_dict.copy()

    def _resolve_group(group_name, visited):
        """Recursively resolve a single group, merging its contents into the main dict."""
        if group_name in visited:
            raise ValueError(f"Circular include detected for group '{group_name}'")
        if group_name not in parser_dict:
            raise KeyError(f"Included group '{group_name}' not found in parser_dict")

        visited.add(group_name)
        group_dict = parser_dict[group_name]
        if not isinstance(group_dict, dict):
            raise TypeError(f"Group '{group_name}' must be a dictionary")

        # Resolve any includes inside this group first
        if 'include' in group_dict:
            includes = group_dict.pop('include')
            if not isinstance(includes, (list, tuple)):
                includes = [includes]
            for inc in includes:
                _resolve_group(inc, visited)

        # Merge the group's key/value pairs into the resolved dict
        for key, value in group_dict.items():
            if key not in resolved:
                resolved[key] = value
            else:
                # If the key already exists, prefer the existing value
                # but if both are dicts, merge them recursively
                if isinstance(resolved[key], dict) and isinstance(value, dict):
                    resolved[key] = _merge_dicts(resolved[key], value)

        visited.remove(group_name)

    def _merge_dicts(a, b):
        """Recursively merge two dictionaries, preferring values from 'a'."""
        result = a.copy()
        for key, value in b.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = _merge_dicts(result[key], value)
            else:
                result[key] = value
        return result

    # Resolve top-level includes if present
    try:
        if 'include' in resolved:
            includes = resolved.pop('include')
            if not isinstance(includes, (list, tuple)):
                includes = [includes]
            for inc in includes:
                _resolve_group(inc, set())
    except Exception as exc:
        raise RuntimeError(f"Error while resolving includes: {exc}") from exc

    return resolved

