def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Attempt to retrieve the spec attribute
        spec = getattr(self, "spec", None)
        if isinstance(spec, dict):
            # If the spec contains a dedicated 'defaults' key, use it
            if "defaults" in spec and isinstance(spec["defaults"], dict):
                defaults.update(spec["defaults"])
            else:
                # Otherwise, treat the entire spec dict as defaults
                defaults.update(spec)
        elif isinstance(spec, (list, tuple)):
            # Support spec as a list/tuple of (arg, default) pairs
            for item in spec:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    defaults[key] = value

        # Merge in any additional defaults from a private attribute
        other = getattr(self, "_defaults", None)
        if isinstance(other, dict):
            for key, value in other.items():
                defaults.setdefault(key, value)

    except Exception as exc:
        # Provide a clear error message while preserving the original exception
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

    return defaults

