def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise TypeError("command_name must be a non-empty string")

    # Attempt to retrieve the command from the parser
    try:
        # The parser is expected to expose a mapping of command names to command objects
        command = self.parser.commands[command_name]
    except (AttributeError, KeyError, TypeError):
        raise ValueError(f"Command '{command_name}' not found in parser")

    # Retrieve the options from the command object
    try:
        options = command.options
    except AttributeError:
        raise AttributeError(f"Command '{command_name}' has no 'options' attribute")

    # Ensure the result is a list
    if not isinstance(options, list):
        try:
            options = list(options)
        except Exception as exc:
            raise TypeError(f"Unable to convert options of command '{command_name}' to a list: {exc}") from exc

    return options

