    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        raise TypeError("args cannot be None")

    try:
        # Handle dictionary of named arguments
        if isinstance(args, dict):
            for key, value in args.items():
                min_val = getattr(self, f"min_{key}", None)
                max_val = getattr(self, f"max_{key}", None)
                if min_val is not None and value < min_val:
                    raise ValueError(
                        f"Argument '{key}' value {value} below minimum {min_val}"
                    )
                if max_val is not None and value > max_val:
                    raise ValueError(
                        f"Argument '{key}' value {value} above maximum {max_val}"
                    )

        # Handle positional arguments (list or tuple)
        elif isinstance(args, (list, tuple)):
            min_val = getattr(self, "min", None)
            max_val = getattr(self, "max", None)
            for idx, value in enumerate(args):
                if min_val is not None and value < min_val:
                    raise ValueError(
                        f"Argument at index {idx} value {value} below minimum {min_val}"
                    )
                if max_val is not None and value > max_val:
