                        vars_dict[key] = value
                    else:
                        raise ValueError(f"Invalid string format for extra var: {item}")
                else:
                    raise TypeError(f"Unsupported type in extra_vars: {type(item)}")
        else:
            raise TypeError("extra_vars must be a dict, list, or tuple")
        return vars_dict

