def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Mapping of parser names to expected argument types.
        # Extend this dictionary as new parsers or arguments are added.
        _ARG_TYPES = {
            'main': {
                'verbose': bool,
                'timeout': int,
                'threshold': float,
                'names': list,
            },
            'virsh': {
                'force': bool,
                'memory': int,
                'cpu': int,
            },
            'ospd': {
                'debug': bool,
                'config': str,
            },
        }

        # Retrieve the type mapping for the given parser; if none, nothing to convert.
        arg_types = _ARG_TYPES.get(parser_name, {})
        if not arg_types:
            return

        for key, val in list(values_dict.items()):
            if key not in arg_types:
                continue

            target_type = arg_types[key]
            try:
                if target_type is bool:
                    # Interpret common string representations of booleans.
                    if isinstance(val, str):
                        lowered = val.lower()
                        if lowered in ('true', '1', 'yes', 'on'):
                            casted = True
                        elif lowered in ('false', '0', 'no', 'off'):
                            casted = False
                        else:
                            raise ValueError(f"Cannot cast {val!r} to bool")
                    else:
                        casted = bool(val)
                elif target_type is list:
                    # Assume comma‑separated string for list arguments.
                    if isinstance(val, str):
                        casted = [item.strip() for item in val.split(',') if item.strip()]
                    else:
                        casted = list(val)
                else:
                    casted = target_type(val)
                values_dict[key] = casted
            except Exception as exc:
                raise ValueError(
                    f"Error converting argument '{key}' to {target_type.__name__}: {exc}"
                ) from exc

