def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory")

    # Find the plugin spec file (JSON or YAML)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'")

    # Load the spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                spec = json.load(f)
            else:
                if yaml is None:
                    raise ImportError("PyYAML is required to parse YAML plugin spec")
                spec = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from '{spec_path}': {exc}") from exc

    if not isinstance(spec, dict):
        raise ValueError(f"Plugin spec must be a mapping, got {type(spec).__name__}")

    # Flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

