def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Helper to strip trailing path separators
    def _rstrip_sep(p):
        while p.endswith('/') or p.endswith('\\'):
            p = p[:-1]
        return p

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    path_norm = _rstrip_sep(path)
    root_norm = _rstrip_sep(root)

    if not root_norm:
        raise ValueError("Root cannot be empty")

    # If the path is exactly the root, return empty string
    if path_norm == root_norm:
        return ''

    # Check for root followed by a separator
    for sep in ('/', '\\'):
        prefix = root_norm + sep
        if path_norm.startswith(prefix):
            return path_norm[len(prefix):]

    # If no match, raise an exception
    raise ValueError(f"Path '{path}' does not start with root '{root}'")

